<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Попадает ли контракт на проектирование под казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Да, на общих основаниях: по порогам и случаям, установленным на год законом о бюджете, либо как контракт в цепочке сопровождаемого госконтракта. Отдельных правил для проектных работ нет."}}, {"@type": "Question", "name": "Почему заказчик не принимает готовую документацию без экспертизы?", "acceptedAnswer": {"@type": "Answer", "text": "Статья 110.2 закона № 44-ФЗ: при обязательной экспертизе проектная документация признаётся результатом работ только при наличии положительного заключения. Без него приёмка юридически невозможна."}}, {"@type": "Question", "name": "Можно ли оплатить госэкспертизу с лицевого счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Проведение государственной экспертизы проектной документации и результатов инженерных изысканий — прямое исключение из запрета перечислений на банковские счета (подпункт 4 пункта 3 статьи 242.23 БК)."}}, {"@type": "Question", "name": "Как платить зарплату проектировщикам с лицевого счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Оплата труда с начислениями — исключение режима: средства переводятся с лицевого счёта на собственный банковский счёт исполнителя под документы о начислении и выплачиваются работникам обычным порядком."}}, {"@type": "Question", "name": "Нужен ли субподрядчику-изыскателю свой лицевой счёт?", "acceptedAnswer": {"@type": "Answer", "text": "Если расчёты с ним подпадают под сопровождение по условиям цепочки — да, с учётом временного порядка расчётов с поставщиками. В договор субподряда включаются условие о сопровождении и идентификатор госконтракта."}}, {"@type": "Question", "name": "Что делать при отрицательном заключении экспертизы?", "acceptedAnswer": {"@type": "Answer", "text": "Дорабатывать документацию и подавать повторно. Расходы на доработку несёт та сторона, чья вина в замечаниях, — поэтому важно фиксировать передачу документации и причины замечаний документально."}}, {"@type": "Question", "name": "Как считается цена проектного контракта?", "acceptedAnswer": {"@type": "Answer", "text": "Заказчик определяет НМЦК по приказу Минстроя № 841/пр — на основе сметных нормативов на проектные и изыскательские работы и справочников базовых цен. После подписания цена фиксированная."}}, {"@type": "Question", "name": "Когда проектировщик получит окончательную оплату?", "acceptedAnswer": {"@type": "Answer", "text": "После подписания документа о приёмке в ЕИС — которому предшествует положительное заключение экспертизы. Срок оплаты при казначейском сопровождении — до десяти рабочих дней с даты подписания документа о приёмке."}}, {"@type": "Question", "name": "Можно ли использовать выполненные разделы в других проектах?", "acceptedAnswer": {"@type": "Answer", "text": "Нет: с даты приёмки исключительные права на результаты принадлежат публичному образованию-заказчику. Собственные типовые решения нужно юридически отделять от результата контракта заранее."}}, {"@type": "Question", "name": "Попадает ли авторский надзор под казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Может попасть — как отдельный договор в цепочке сопровождаемого строительного контракта, если расчёты по нему финансируются целевыми средствами. Условия смотрите в договоре и у заказчика."}}]}
</script>
